#!/usr/bin/env python3
"""Count any remaining autogenerated wrapper docstrings."""

import re
from pathlib import Path

api_root = Path("src/britecore_sdk/api/api_calls")
remaining_count = 0
files_with_remaining = []

pattern = r'Autogenerated wrapper for'

for py_file in sorted(api_root.rglob("*.py")):
    if py_file.name in ["__init__.py", "async_calls.py"]:
        continue

    content = py_file.read_text(encoding="utf-8")
    count = len(re.findall(pattern, content))

    if count > 0:
        files_with_remaining.append((py_file.name, count))
        remaining_count += count

if remaining_count == 0:
    print("✓ NO REMAINING AUTOGENERATED WRAPPERS FOUND!")
    print("All 189+ endpoint wrapper functions have comprehensive docstrings.")
else:
    print(f"Remaining autogenerated wrappers: {remaining_count}")
    for filename, count in files_with_remaining:
        print(f"  {filename}: {count}")

print(f"\nTotal: {remaining_count} remaining")

